<template>
  <view class="family-page safety-game">
    <text class="eyebrow">亲子情境小游戏 · 在家练一练</text><text class="title">安全小侦探</text><text class="intro">帮小妙停一停、看一看，再作决定。<br />真实出行时收起手机，由家长陪同观察。</text>
    <text v-if="error" class="error">{{ error }}</text><button v-if="pending.length && !finished" class="secondary" @click="retryPending">重试保存练习进度</button>
    <template v-if="!scene && !finished"><view class="card welcome"><image src="/static/puzzle/robot-miao.png" mode="aspectFit" /><text class="heading">今天一起发现什么？</text><text class="muted">8 个故事，每个都有三步挑战：发现危险、选择行动、再想一步。</text><button class="primary" @click="startRound">开始 3 个故事 · 优先复习</button></view><view class="scene-grid"><button v-for="item in scenes" :key="item.id" @click="startOne(item.id)"><image class="scene-art" :src="'/static/ui/scene-'+item.id+'.png'" mode="aspectFit" /><text>{{ item.title }}</text><text class="muted">{{ statusFor(item.id) }}</text></button></view></template>
    <template v-else-if="scene && !finished"><view class="row"><text class="pill">{{ scene.place }}</text><text class="muted">{{ cursor+1 }} / {{ ids.length }}</text></view><view class="card story"><image class="story-art" :src="'/static/ui/scene-'+scene.id+'.png'" mode="aspectFit" /><text class="heading">{{ scene.title }}</text><text class="scene-text">{{ scene.scene }}</text></view><text class="stage-label">{{ stepIndex+1 }} / 3 · {{ step.title }}</text><text class="heading">{{ step.prompt }}</text><button v-for="option in options" :key="option.id" :class="['option',{selected:picked===option.id,safe:picked&&option.id===step.answer}]" :disabled="!!picked" @click="choose(option.id)">{{ option.text }}<text v-if="picked && option.id===step.answer"> ✓</text></button>
      <view v-if="picked" class="card explanation"><text class="heading">{{ picked===step.answer ? '这个选择照顾到了安全' : '先停住，一起换个办法' }}</text><text class="scene-text">{{ chosenConsequence }}<br />{{ step.why }}</text><view class="reminder">记住这句：{{ scene.reminder }}</view><text class="heading talk-heading">和家长说一说</text><text class="scene-text">{{ scene.talk }}</text><text class="muted">选对不等于已经养成习惯，实际出行还要一起练。</text><button class="primary next" @click="next">{{ stepIndex<2 ? '继续下一步' : cursor===ids.length-1 ? '完成这一轮' : '下一个故事' }}</button><button class="link" @click="showSources=!showSources">{{ showSources ? '收起依据' : '看看安全依据' }}</button><template v-if="showSources"><button v-for="source in currentSources" :key="source.url" class="source-link" @click="copySource(source)">{{ source.title }} · 复制链接</button><text class="muted">情境和问答为原创；链接仅供家长查阅。</text></template></view><button class="link" @click="returnToList">先到这里，回故事列表</button></template>
    <view v-else class="card finish"><text class="finish-icon">✦</text><text class="heading">一起聊过 {{ ids.length }} 个故事</text><view v-for="id in ids" :key="id" class="takeaway"><text class="scene-text">{{ byId[id].reminder }}</text><text v-if="discuss.includes(id)" class="muted">值得下次再聊一聊</text></view><text v-if="pending.length" class="error">还有 {{ pending.length }} 项练习进度未保存。</text><button v-if="pending.length" class="secondary" @click="retryPending">重试保存</button><text class="muted">出门前选一句约定，回家再聊一次具体经历。</text><button class="primary" @click="garden">去成长小花园记一件小事</button><button class="link" @click="returnToList">回到故事列表</button></view>
  </view>
</template>
<script>
import { safetyScenes, SAFETY_SOURCES } from '@/data/safety-scenes.mjs'
import { shuffle } from '@/knowledge/model.mjs'
import { safetyLearningStore } from '@/services/safety-learning.js'
import { readSafetyLearning, summarizeSafetyLearning, safetyPracticeIds } from '@/game/safety-learning.mjs'
import { familyGameStore } from '@/services/family.js'
export default {
  data() { return { scenes:safetyScenes, byId:Object.fromEntries(safetyScenes.map(scene=>[scene.id,scene])), ids:[], cursor:0, options:[], picked:'', finished:false, seen:[], discuss:[], pending:[], error:'', showSources:false,stepIndex:0,eventSequence:0,learning:readSafetyLearning('') } },
  computed: { step(){return this.scene?.steps[this.stepIndex]},chosenConsequence(){return this.step?.options.find(o=>o.id===this.picked)?.consequence||''}, scene() { return this.byId[this.ids[this.cursor]] }, currentSources() { return this.scene?.sources.map(index=>SAFETY_SOURCES[index]) || [] } },
  onLoad() { try { this.seen=familyGameStore.read().scenes;this.learning=safetyLearningStore.read() } catch(error) { this.error=error.message } },
  onBackPress(){if(!this.pending.length)return false;uni.showModal({title:'还有进度未保存',content:'可以留下重试保存，或放弃本次未保存的进度。',confirmText:'留下重试',cancelText:'放弃离开',success:r=>{if(r.cancel){this.pending=[];uni.navigateBack()}}});return true},
  methods: {
    begin(ids) { this.ids=ids; this.cursor=0; this.finished=false; this.discuss=[]; this.prepare(true) },
    startRound() { this.begin(safetyPracticeIds(this.learning)) },
    startOne(id) { this.begin([id]) },
    prepare(reset=false) { if(reset)this.stepIndex=0;this.options=shuffle(this.step.options); this.picked=''; this.showSources=false; uni.pageScrollTo({scrollTop:0,duration:0}) },
    statusFor(id){const p=this.learning.scenes[id];return p?.review.length?'有待复习的判断':p?.passed.length===3?'三步已独立完成':p?'独立完成 '+p.passed.length+'/3 步':this.byId[id].place},
    choose(id) {if(this.picked||!this.step.options.some(option=>option.id===id))return;this.picked=id;const correct=id===this.step.answer;if(!correct&&!this.discuss.includes(this.scene.id))this.discuss.push(this.scene.id);this.persist({id:++this.eventSequence,kind:'step',scene:this.scene.id,step:this.step.id,correct});if(this.stepIndex===2)this.persist({id:++this.eventSequence,kind:'seen',scene:this.scene.id})},
    persist(event){if(!this.pending.some(e=>e.id===event.id))this.pending.push(event);return this.retryPending()},
    retryPending(){while(this.pending.length){const e=this.pending[0];try{if(e.kind==='seen')this.seen=familyGameStore.mark('scenes',e.scene).scenes;else this.learning=safetyLearningStore.save(e.scene,e.step,e.correct);this.pending.shift()}catch(error){this.error='练习进度尚未保存，请重试后再离开。';return false}}this.error='';return true},
    next() {if(!this.picked||this.finished)return;if(this.stepIndex<2){this.stepIndex++;this.prepare()}else if(this.cursor===this.ids.length-1)this.finished=true;else{this.cursor++;this.prepare(true)};uni.pageScrollTo({scrollTop:0,duration:0})},
    returnToList() { this.ids=[]; this.finished=false; uni.pageScrollTo({scrollTop:0,duration:0}) },
    garden() { uni.navigateTo({url:'/pages/growth/index'}) },
    copySource(source) { uni.setClipboardData({data:source.url}) }
  }
}
</script>
<style src="@/styles/family.css"></style>
<style scoped>
.stage-label{display:block;margin:18px 0 10px;color:#2467b5;font-size:13px;font-weight:600}.welcome { text-align:center; }.welcome image { width:75px; height:90px; }.welcome .primary { margin-top:20px; }.scene-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:12px; }.scene-grid button { width:100%; padding:15px 9px; margin:0; font-size:13px; color:#436889; background:#fff; line-height:1.8; border:1px solid #dce8f4; border-bottom-width:3px; }.scene-art { display:block; width:100%; height:74px; margin-bottom:12px; border-radius:10px; }.story-art { display:block; width:100%; height:125px; margin:0 0 16px; border-radius:12px; }
.scene-icon { display:block; font-size:38px; margin-bottom:10px; }.scene-grid .muted { font-size:12px; margin-top:8px; }.story { margin:18px 0; background:#fff8e8; text-align:center; }.scene-text { display:block; font-size:15px; line-height:1.9; white-space:pre-wrap; }.option { width:100%; white-space:normal; text-align:left; padding:15px; margin:12px 0; background:#fff; color:#486b94; border:2px solid #e0eaf5; font-size:14px; line-height:1.8; }.option[disabled] { opacity:1; color:#5b6877; }.option.selected { border-color:#94b3d7; }.option.safe { background:#eaf6ee; border-color:#77b59a; color:#377b64; }.explanation { margin-top:23px; }.reminder { background:#e8f1ff; color:#3f6da3; font-weight:600; font-size:15px; line-height:1.8; border-radius:12px; padding:12px; margin:18px 0; }.talk-heading { margin-top:20px; }.explanation .muted { margin-top:15px; font-size:12px; }.next { margin-top:20px; }.source-link { display:block; width:100%; padding:7px; background:#f0f5fb; color:#4f6781; font-size:12px; line-height:1.8; margin:8px 0; text-align:left; }.finish { text-align:center; }.finish-icon { display:block; color:#816533; font-size:55px; margin-bottom:12px; }.takeaway { margin:18px 0; padding:10px; border-radius:12px; background:#edf4fd; }.finish .primary { margin-top:20px; font-size:12px; }
</style>
